#!/bin/sh
set -e

REPO_DIR="$(cd "$(dirname "$0")" && pwd)"

# Backup existing .vimrc if present
if [ -f "$HOME/.vimrc" ]; then
    BACKUP="$HOME/.vimrc.backup.$(date +%Y%m%d_%H%M%S)"
    cp "$HOME/.vimrc" "$BACKUP"
    echo "Backed up existing ~/.vimrc to $BACKUP"
fi

cat << EOF > "$HOME/.vimrc"
" DO NOT EDIT THIS FILE
" Add your own customizations in ${REPO_DIR}/my_configs.vim

set packpath^=${REPO_DIR}
set runtimepath^=${REPO_DIR}

source ${REPO_DIR}/vimrcs/basic.vim
source ${REPO_DIR}/vimrcs/filetypes.vim
source ${REPO_DIR}/vimrcs/plugins_config.vim
source ${REPO_DIR}/vimrcs/extended.vim

try
  source ${REPO_DIR}/my_configs.vim
catch
endtry
EOF

# Generate documentation tags once after installation
if command -v vim >/dev/null 2>&1; then
    vim -es -u "$HOME/.vimrc" -c "helptags ALL" -c "q" 2>/dev/null || true
fi

echo "Installed the Ultimate Vim configuration successfully! Enjoy :-)"
